import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { HEARTBEAT_STALE_MS, openDatabase, toJob, type JobRow } from './db.ts';

interface Field {
  field: string;
  message: string;
}

const MAX_BODY_BYTES = 1_000_000;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectHeartbeat = db.prepare("SELECT ts FROM heartbeat WHERE name = 'worker'");
const insertJob = db.prepare(
  `INSERT INTO jobs(id, status, input, steps, fail_attempts, attempts, progress_completed,
     idempotency_key, payload, next_run_at, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: Field[]): void {
  const error: { code: string; message: string; fields?: Field[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function readBody(req: IncomingMessage): Promise<{ buf: Buffer; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ buf: Buffer.concat(chunks), tooLarge }));
    req.on('error', reject);
  });
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Validates an optional integer field; returns the value (or default) or undefined if invalid. */
function integerField(
  fields: Field[],
  name: string,
  value: unknown,
  fallback: number,
  min: number,
  max: number,
): number | undefined {
  if (value === undefined) return fallback;
  if (typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max) return value;
  fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
  return undefined;
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { buf, tooLarge } = await readBody(req);
  const fields: Field[] = [];
  const addBodyError = (message: string): void => {
    if (!fields.some((f) => f.field === 'body')) fields.push({ field: 'body', message });
  };

  const mediaType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') addBodyError('Content-Type must be application/json');

  const key = req.headers['idempotency-key'];
  if (key !== undefined && (typeof key !== 'string' || !IDEMPOTENCY_KEY_RE.test(key))) {
    fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  if (tooLarge) addBodyError('Request body is too large');

  let body: Record<string, unknown> | undefined;
  if (mediaType === 'application/json' && !tooLarge) {
    try {
      const parsed: unknown = JSON.parse(buf.toString('utf8'));
      if (isPlainObject(parsed)) body = parsed;
      else addBodyError('Body must be a JSON object');
    } catch {
      addBodyError('Body must be valid JSON');
    }
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  if (body) {
    for (const name of Object.keys(body)) {
      if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'Unknown field' });
    }
    const rawInput = body.input;
    if (typeof rawInput !== 'string') {
      fields.push({ field: 'input', message: 'input is required and must be a string' });
    } else if (rawInput.length < 1 || rawInput.length > 1000) {
      fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
    } else if (rawInput.trim() === '') {
      fields.push({ field: 'input', message: 'input must not be only whitespace' });
    } else {
      input = rawInput;
    }
    const s = integerField(fields, 'steps', body.steps, 5, 1, 20);
    const f = integerField(fields, 'failAttempts', body.failAttempts, 0, 0, 5);
    if (s !== undefined) steps = s;
    if (f !== undefined) failAttempts = f;
  }

  if (fields.length > 0) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
    return;
  }

  const idempotencyKey = typeof key === 'string' ? key : null;
  const payload = JSON.stringify({ input, steps, failAttempts });

  // Synchronous and short: BEGIN IMMEDIATE takes the write lock up front, so the key check and
  // insert cannot interleave with another process's submission.
  db.exec('BEGIN IMMEDIATE');
  try {
    if (idempotencyKey !== null) {
      const existing = selectByKey.get(idempotencyKey) as unknown as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload === payload) send(res, 200, toJob(existing));
        else
          sendError(
            res,
            409,
            'idempotency_conflict',
            'This Idempotency-Key was already used with a different payload.',
          );
        return;
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    insertJob.run(id, input, steps, failAttempts, idempotencyKey, payload, now, now);
    const row = selectById.get(id) as unknown as JobRow;
    db.exec('COMMIT');
    send(res, 201, toJob(row));
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
  const method = req.method ?? 'GET';

  let route: 'home' | 'health' | 'jobs' | 'job' | undefined;
  let jobId = '';
  if (path === '/') route = 'home';
  else if (path === '/health') route = 'health';
  else if (path === '/api/jobs') route = 'jobs';
  else {
    const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
    if (match) {
      route = 'job';
      jobId = match[1]!;
    }
  }

  if (!route) {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }
  const allowed: Record<typeof route, string[]> = {
    home: ['GET'],
    health: ['GET'],
    jobs: ['GET', 'POST'],
    job: ['GET'],
  };
  if (!allowed[route].includes(method)) {
    sendError(res, 405, 'method_not_allowed', `${method} is not allowed on this route.`);
    return;
  }

  switch (route) {
    case 'home':
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(uiHtml);
      return;
    case 'health': {
      const row = selectHeartbeat.get() as { ts: number } | undefined;
      const up = row !== undefined && Date.now() - row.ts < HEARTBEAT_STALE_MS;
      send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
      return;
    }
    case 'jobs':
      if (method === 'POST') {
        await handleCreateJob(req, res);
        return;
      }
      send(res, 200, { jobs: (selectAll.all() as unknown as JobRow[]).map(toJob) });
      return;
    case 'job': {
      const row = selectById.get(jobId) as unknown as JobRow | undefined;
      if (!row) sendError(res, 404, 'not_found', 'No job with that id.');
      else send(res, 200, toJob(row));
      return;
    }
  }
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Something went wrong.');
    else res.end();
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // UI polling keeps connections alive, so close them explicitly or server.close() never finishes.
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2000).unref();
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

