import { setTimeout as sleep } from 'node:timers/promises';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, openDatabase, type JobRow } from './db.ts';

/** Duration of one processing step (or of the first step of a failing attempt). */
const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 500;

const db = openDatabase();
let stopping = false;

const now = (): string => new Date().toISOString();

const beat = db.prepare(
  "INSERT INTO heartbeat(name, ts) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET ts = excluded.ts",
);
const heartbeatTimer = setInterval(() => beat.run(Date.now()), HEARTBEAT_MS);
beat.run(Date.now());

// A job left in 'running' by a dead worker is requeued. Its interrupted attempt does not count.
db.prepare(
  "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, next_run_at = 0, updated_at = ? WHERE status = 'running'",
).run(now());

const pickNext = db.prepare(
  "SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1",
);
const claim = db.prepare(
  "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
);
const setProgress = db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?');
const setRetry = db.prepare(
  "UPDATE jobs SET status = 'queued', next_run_at = ?, progress_completed = 0, updated_at = ? WHERE id = ?",
);
const setFailed = db.prepare(
  "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, progress_completed = 0, updated_at = ? WHERE id = ?",
);
const setCompleted = db.prepare(
  "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = steps, updated_at = ? WHERE id = ?",
);
const requeueInterrupted = db.prepare(
  "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, next_run_at = 0, updated_at = ? WHERE id = ? AND status = 'running'",
);

/** Runs one attempt. `n` is the attempt number, counting from 1. */
async function runAttempt(job: JobRow, n: number): Promise<void> {
  const requeueAndStop = (): void => {
    requeueInterrupted.run(now(), job.id);
  };

  if (n <= job.fail_attempts) {
    // Simulated transient failure: fails at its first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return requeueAndStop();
    if (n < MAX_ATTEMPTS) setRetry.run(Date.now() + RETRY_DELAY_MS, now(), job.id);
    else setFailed.run(now(), job.id);
    return;
  }

  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) return requeueAndStop();
    setProgress.run(i, now(), job.id);
  }
  setCompleted.run(job.input.toUpperCase(), now(), job.id);
}

function onSignal(): void {
  stopping = true;
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, onSignal);

console.log('worker started');
while (!stopping) {
  const next = pickNext.get(Date.now()) as unknown as JobRow | undefined;
  if (!next) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  if (Number(claim.run(now(), next.id).changes) !== 1) continue;
  await runAttempt(next, next.attempts + 1);
}

clearInterval(heartbeatTimer);
db.prepare("UPDATE heartbeat SET ts = 0 WHERE name = 'worker'").run();
db.close();
console.log('worker stopped');
process.exit(0);

